3	import java.time.Clock;
4	import java.time.LocalDateTime;
5	import java.util.LinkedHashMap;
6	import java.util.Map;
7	import java.util.Optional;
8	import java.util.function.Supplier;
9	
10	import org.springframework.dao.DuplicateKeyException;
11	import org.springframework.stereotype.Component;
12	
13	import com.example.starter.rt.domain.OperationType;
14	import com.example.starter.rt.dto.RecordedResponse;
15	import com.example.starter.rt.repository.WorkflowRepository;
16	import com.example.starter.rt.repository.WorkflowRepository.IdempotentRow;
17	import com.example.starter.rt.support.Fingerprint;
18	import com.example.starter.rt.web.ApiException;
19	import com.fasterxml.jackson.core.JsonProcessingException;
20	import com.fasterxml.jackson.databind.ObjectMapper;
21	
22	/**
23	 * requestId 幂等执行模板：
24	 * <ul>
25	 *   <li>指纹覆盖 requestId、操作类型与全部业务字段；</li>
26	 *   <li>同键同参：返回首次结果（含首次业务拒绝 422/409），含 replayed 字段的成功响应置 replayed=true；</li>
27	 *   <li>同键异参：抛 409，不执行业务、不产生新分次；</li>
28	 *   <li>并发同键：调用方已持有患者/版本行锁，同实体并发请求被行锁串行化，负者读到首次结果重放。</li>
29	 * </ul>
30	 * 模板不自行开启事务，参与调用方 Service 的事务边界；首次结果与业务写库同事务提交。
31	 */
32	@Component
33	public class IdempotencyTemplate {
34	
35	    private final WorkflowRepository workflow;
36	    private final ObjectMapper objectMapper;
37	    private final Clock clock;
38	
39	    public IdempotencyTemplate(WorkflowRepository workflow, ObjectMapper objectMapper, Clock clock) {
40	        this.workflow = workflow;
41	        this.objectMapper = objectMapper;
42	        this.clock = clock;
43	    }
44	
45	    /**
46	     * 按 requestId 幂等执行业务动作。动作须以 {@link RecordedResponse} 返回全部业务结论
47	     * （成功与业务拒绝），不在动作内抛业务异常，以保证首次结果与业务写库同事务提交留痕。
48	     */
49	    public RecordedResponse execute(OperationType operation, String requestId, Map<String, ?> params,
50	                                    Supplier<RecordedResponse> action) {
51	        String fingerprint = Fingerprint.of(operation, requestId, params);
52	        Optional<IdempotentRow> existing = workflow.findIdempotent(requestId);
53	        if (existing.isPresent()) {
54	            return replayOrConflict(existing.get(), fingerprint);
55	        }
56	
57	        RecordedResponse result = action.get();
58	        try {
59	            workflow.insertIdempotent(requestId, operation.name(), fingerprint,
60	                    result.httpStatus(), writeJson(result.body()), LocalDateTime.now(clock));
61	        } catch (DuplicateKeyException concurrent) {
62	            // 非同实体跨行并发：唯一约束决胜，负者整个事务回滚并返回 409（正常同实体并发已被行锁串行化为重放）。
63	            throw ApiException.conflict("IDEMPOTENCY_RACE",
64	                    "requestId=" + requestId + " 并发冲突，仅一个请求生效");
65	        }
66	        return result;
67	    }
68	
69	    private RecordedResponse replayOrConflict(IdempotentRow row, String fingerprint) {
70	        if (!row.fingerprint().equals(fingerprint)) {
71	            throw ApiException.conflict("IDEMPOTENCY_FINGERPRINT_CONFLICT",
72	                    "requestId=" + row.requestId() + " 已绑定不同业务参数，拒绝执行（409）");
73	        }
74	        return new RecordedResponse(row.httpStatus(), markReplayed(readJson(row.responseJson())));
75	    }
76	
77	    /** 重放响应在保留首次业务字段的前提下，将 replayed 标记置为 true。 */
78	    @SuppressWarnings("unchecked")
79	    private Object markReplayed(Object body) {
80	        if (body instanceof Map<?, ?> map && map.containsKey("replayed")) {
81	            Map<String, Object> mutable = new LinkedHashMap<>((Map<String, Object>) map);
82	            mutable.put("replayed", true);
83	            return mutable;
84	        }
85	        return body;
86	    }
87	
88	    private String writeJson(Object body) {
89	        try {
90	            return objectMapper.writeValueAsString(body);
91	        } catch (JsonProcessingException e) {
92	            throw new IllegalStateException("幂等响应序列化失败", e);
93	        }
94	    }
95	
96	    private Object readJson(String json) {
97	        try {
98	            return objectMapper.readValue(json, Object.class);
99	        } catch (JsonProcessingException e) {
100	            throw new IllegalStateException("幂等响应反序列化失败", e);
101	        }
102	    }
103	}
