package com.example.starter.rt.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 设备能力下调请求。能力只能下调不能上调；携带 expectedVersion 做乐观并发门禁，
 * 成功下调后设备版本加1。
 *
 * @param deviceId           设备ID
 * @param expectedVersion    客户端所见设备版本（从1开始），与当前不一致返回409
 * @param newCapabilityLevel 下调后的可执行最高复杂度等级（1-3，且必须低于当前等级）
 * @param requestId          幂等键
 */
public record DeviceCapabilityRequest(
        @NotBlank(message = "不能为空") String deviceId,
        @NotNull(message = "不能为空") @Positive(message = "须为正数") Integer expectedVersion,
        @NotNull(message = "不能为空")
        @Min(value = 1, message = "复杂度等级取值为1至3")
        @Max(value = 3, message = "复杂度等级取值为1至3") Integer newCapabilityLevel,
        @NotBlank(message = "不能为空") String requestId) {
}

package com.example.starter.rt.dto;

import java.time.OffsetDateTime;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 批量排程中的单个分次排程项。窗口为 UTC 半开区间 [windowStartUtc, windowEndUtc)，
 * 长度须恰为复杂度等级对应固定分钟数（等级1/2/3→10/20/30分钟）。
 *
 * @param fractionNo      分次号（该分次须尚未执行且未被占用）
 * @param deviceId        设备ID
 * @param complexityLevel 冻结的复杂度等级（1-3），不得高于设备当前能力
 * @param windowStartUtc  窗口起点UTC（含）
 * @param windowEndUtc    窗口终点UTC（不含）
 */
public record ScheduleItemRequest(
        @NotNull(message = "不能为空") @Positive(message = "须为正数") Integer fractionNo,
        @NotBlank(message = "不能为空") String deviceId,
        @NotNull(message = "不能为空")
        @Min(value = 1, message = "复杂度等级取值为1至3")
        @Max(value = 3, message = "复杂度等级取值为1至3") Integer complexityLevel,
        @NotNull(message = "不能为空") OffsetDateTime windowStartUtc,
        @NotNull(message = "不能为空") OffsetDateTime windowEndUtc) {
}

package com.example.starter.rt.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

/**
 * 分次设备时长排程批量发布请求。单次最多10个连续分次；发布冻结计划版本、等级、设备与UTC窗口，
 * 原子占用设备时长与分次资源，任一冲突整批零占用。
 *
 * @param patientId 患者ID
 * @param planCode  计划业务编码
 * @param versionNo 要引用的计划版本号（须为已批准且首次验证合格的当前版本）
 * @param requestId 发布幂等键，同批分次共享；失败不占键
 * @param items     连续分次排程项（1至10个）
 */
public record SchedulePublishRequest(
        @NotBlank(message = "不能为空") String patientId,
        @NotBlank(message = "不能为空") String planCode,
        @NotNull(message = "不能为空") @Positive(message = "须为正数") Integer versionNo,
        @NotBlank(message = "不能为空") String requestId,
        @NotEmpty(message = "至少发布一个分次排程")
        @Size(max = 10, message = "单次批量排程最多10个连续分次")
        @Valid List<ScheduleItemRequest> items) {
}

package com.example.starter.rt.dto;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 排程取消请求。仅 BOOKED（已发布未完成）排程可取消；取消原子释放设备时长与分次占用。
 *
 * @param scheduleId      排程ID
 * @param expectedVersion 客户端所见排程版本（发布为1，取消/执行成功后为2），不一致返回409
 * @param requestId       取消幂等键；失败不占键
 */
public record ScheduleCancelRequest(
        @NotNull(message = "不能为空") @Positive(message = "须为正数") Long scheduleId,
        @NotNull(message = "不能为空") @Positive(message = "须为正数") Integer expectedVersion,
        @NotBlank String requestId) {
}

