        this.clock = clock;
    }

    @Override
    @Transactional
    public void run(ApplicationArguments args) {
        if (!directoryRepository.patientExists(PATIENT_ID)
                || !directoryRepository.templateExists(TEMPLATE_CODE)) {
            return;
        }
